package com.agateau.pixelwheels.bonus;

import com.agateau.pixelwheels.racer.Racer;
import com.badlogic.gdx.utils.Pool;

/** A missile bonus */
public class MissileBonus extends BonusAdapter implements Pool.Poolable {
    private Missile mMissile;

    private boolean mTriggered;
    private boolean mOwnerHit;

    public MissileBonus() {
        reset();
    }

    @Override
    public void reset() {
        mTriggered = false;
        mOwnerHit = false;
    }

    @Override
    public void onPicked(Racer racer) {
        super.onPicked(racer);
        mMissile = Missile.create(mAssets, mGameWorld, mAudioManager, mRacer);
    }

    @Override
    public void onOwnerHit() {
        mOwnerHit = true;
    }

    @Override
    public void trigger() {
        mTriggered = true;
    }

    @Override
    public void act(float delta) {
        if (mTriggered) {
            mMissile.shoot();
            resetBonus();
        }
        if (mOwnerHit) {
            mMissile.remove();
            resetBonus();
        }
    }

    @Override
    public void aiAct(float delta) {
        if (mMissile.hasTarget()) {
            trigger();
        }
    }

    private void resetBonus() {
        free();
        mRacer.resetBonus();
    }
}
