    @Override
    public void dispose() {
        sPool.free(this);
    }

    @Override
    public void act(float delta) {}

    @Override
    public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {
        if (zLevel != ZLevel.GROUND) {
            return;
        }
        float radius = mBody.getFixtureList().get(0).getShape().getRadius();
        if (!AgcMathUtils.rectangleContains(viewBounds, getPosition(), radius)) {
            return;
        }
        mDrawer.setBatch(batch);
        mDrawer.draw(mBody, mAssets.bullet);
    }

    @Override
    public void audioRender(AudioClipper clipper) {
        if (mJustShot) {
            mAudioManager.play(mAssets.soundAtlas.get("shoot"), clipper.clip(this));

    @Override
    public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {
        if (zLevel != ZLevel.OBSTACLES && zLevel != ZLevel.SHADOWS) {
            return;
        }
        if (!AgcMathUtils.rectangleContains(viewBounds, getPosition(), mRegionRadius)) {
            return;
        }
        if (zLevel == ZLevel.OBSTACLES) {
            mBodyRegionDrawer.setBatch(batch);
            mBodyRegionDrawer.draw(mBody, mRegion);
        } else {
            mBodyRegionDrawer.setBatch(batch);
            mBodyRegionDrawer.drawShadow(mBody, mRegion);
        }
    }

    @Override
    public float getX() {
        return mBody.getPosition().x;
    }

    @Override
    public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {
        if (!AgcMathUtils.rectangleContains(viewBounds, getPosition(), mFrameBufferRadiusU)) {
            return;
        }
        if (zLevel == ZLevel.SHADOWS) {
            float old = batch.getPackedColor();
            batch.setColor(0, 0, 0, SHADOW_ALPHA);
            float offset = SHADOW_OFFSET * Constants.UNIT_FOR_PIXEL;
            drawFrameBuffer(batch, offset);
            batch.setPackedColor(old);
        } else if (zLevel == ZLevel.FLYING) {
            drawFrameBuffer(batch, 0);
        }
    }

    @SuppressWarnings("SuspiciousNameCombination")
    private void updateFrameBuffer() {
        final float w = mBodyRegion.getRegionWidth();
        final float h = mBodyRegion.getRegionHeight();

        float propellerW = mPropellerRegion.getRegionWidth();
        float propellerH = mPropellerRegion.getRegionHeight();

        float propellerTopW = mPropellerTopRegion.getRegionWidth();
        float propellerTopH = mPropellerTopRegion.getRegionHeight();

        mFrameBuffer.begin();
        mFrameBufferBatch.begin();
        Gdx.gl.glClearColor(0, 0, 0, 0);
        Gdx.gl.glClear(GL20.GL_COLOR_BUFFER_BIT);

        mFrameBufferBatch.draw(mBodyRegion, propellerW / 2 - BODY_CENTER.x, 0, w, h);

        mFrameBufferBatch.draw(
                mPropellerRegion,
                0,
                BODY_CENTER.y - propellerH / 2, // position
                propellerW / 2,
                propellerH / 2, // origin
                propellerW,
                propellerH, // size
                1,
                1, // scale
                (mTime * PROPELLER_SPEED) % 360);

        mFrameBufferBatch.draw(
                mPropellerTopRegion,
                propellerW / 2 - propellerTopW / 2,
                BODY_CENTER.y - propellerTopH / 2,
                propellerTopW,
                propellerTopH);

        mFrameBufferBatch.end();
        mFrameBuffer.end();
    }

    private void drawFrameBuffer(Batch batch, float offset) {
        final float U = Constants.UNIT_FOR_PIXEL;
        int w = mFrameBuffer.getWidth();
        int h = mFrameBuffer.getHeight();
        Texture texture = mFrameBuffer.getColorBufferTexture();
        batch.draw(
                texture,
                // dst
                getX() - w * U / 2 + offset,
                getY() - BODY_CENTER.y * U - offset,
                // origin
                w * U / 2,
                BODY_CENTER.y * U,
                // dst size
                w * U,
                h * U,
                // scale
                1,
                1,
                // rotation
                mAngle - 90,
                // src
                0,
                0,
        }
    }

    @Override
    public void draw(Batch batch, ZLevel zLevel, Rectangle viewBounds) {
        if (!mBody.isActive()) {
            return;
        }
        if (!AgcMathUtils.rectangleContains(viewBounds, getPosition(), sRegionRadiusU)) {
            return;
        }
        if (zLevel == ZLevel.GROUND) {
            mDrawer.setBatch(batch);
            mDrawer.drawShadow(mBody, mRegion);
        } else if (zLevel == ZLevel.OBSTACLES) {
            mDrawer.setBatch(batch);
            mDrawer.draw(mBody, mRegion);
        }
    }

