            if (z == ZLevel.OBSTACLES && mForegroundLayerIndexes.length > 0) {
                mGameObjectPerformanceCounter.stop();
                mTilePerformanceCounter.start();

                mBatch.end();
                mRenderer.render(mForegroundLayerIndexes);
                mBatch.begin();

                mTilePerformanceCounter.stop();
                mGameObjectPerformanceCounter.start();
            }
        }
        mBatch.end();
        mGameObjectPerformanceCounter.stop();

        if (Debug.instance.showDebugLayer) {
                Box2DUtils.setCollisionInfo(info.wheel.getBody(), 0, 0);
            }
        } else {
            // Landing
            applyCollisionInfo();
        }
        mFlying = flying;
    }

    public boolean isFlying() {
        return mFlying;
    }

    public boolean isFalling() {
        return mZ < 0;
    }

    public float getZ() {
        return mZ;
    }

    public void setZ(float z) {
        mZ = z;
    }

    /** Call this when the vehicle needs to stop as soon as possible For example because it fell */
    public void setStopped(boolean stopped) {
        if (stopped) {
            mTurboTime = -1;
        }
        mStopped = stopped;
    }

    @Override
    public void act(float dt) {
        if (!isFlying()) {
            if (mStopped) {
                actStopping(dt);
            } else {
                applyTurbo(dt);
                applyPilotCommands();
                applyGroundEffects(dt);
                updateMaterial();
            }
        }
        actWheels(dt);
    }

